NHScpuExecResult nh_v07_shard_00CE2C(NHScpuState *cpu, const NHScpuBus *bus) {
    size_t lo=0u, hi=107u;
    const uint32_t key=nh_scpu_context_key(cpu);
    while (lo < hi) {
        const size_t mid=lo+(hi-lo)/2u;
        const NHSharedRecord *r=&records_00CE2C[mid];
        if (key < r->key) hi=mid;
        else if (key > r->key) lo=mid+1u;
        else return nh_v18_shared_execute(cpu,bus,r->body,parameters_00CE2C+r->offset);
    }
    return NH_SCPU_NOT_MINE;
}

